/**
 * Orvix Response Alternatives Service
 * Handles data structures, relationships, normalization, and switching
 * for multiple assistant response alternatives associated with a single user message.
 *
 * Architecture:
 * - A single user message (identified by stable `id`, e.g., 'user-1718000000000') can have
 *   multiple associated assistant response alternatives generated by different AI providers/models.
 * - Each alternative is an independently identifiable record with its own content, provider,
 *   modelUsed, responseTimeMs, timestamp, and metadata.
 * - The assistant message contains an `alternatives` collection and points to `activeAlternativeId`.
 * - The active alternative is projected onto root message properties (`content`, `provider`, `modelUsed`,
 *   `responseTimeMs`) to preserve seamless backward compatibility with all existing rendering,
 *   streaming, clipboard copying, voice read-aloud, and export systems.
 */

/**
 * Generates a stable, unique identifier for a response alternative.
 * @param {string} [provider='assistant']
 * @returns {string}
 */
export function generateAlternativeId(provider = 'assistant') {
  const cleanProvider = (provider || 'assistant').toLowerCase().replace(/[^a-z0-9_-]/g, '');
  const timestamp = Date.now();
  const randomPart = Math.random().toString(36).substring(2, 8);
  return `alt-${cleanProvider}-${timestamp}-${randomPart}`;
}

/**
 * Creates a well-formed Response Alternative record.
 *
 * @param {Object} params
 * @param {string} [params.id]
 * @param {string|null} [params.parentMessageId=null] - The user message ID that prompted this alternative
 * @param {string} [params.content='']
 * @param {string} [params.provider='gemini']
 * @param {string|null} [params.modelUsed=null]
 * @param {number|null} [params.responseTimeMs=null]
 * @param {string} [params.timestamp='']
 * @param {number} [params.createdAt=Date.now()]
 * @param {Array} [params.referencedAttachments=[]]
 * @param {boolean} [params.isError=false]
 * @param {boolean} [params.isStopped=false]
 * @returns {Object} Clean ResponseAlternative object
 */
export function createAlternativeRecord({
  id = null,
  parentMessageId = null,
  content = '',
  provider = 'gemini',
  modelUsed = null,
  responseTimeMs = null,
  timestamp = '',
  createdAt = null,
  referencedAttachments = [],
  isError = false,
  isStopped = false
} = {}) {
  const chosenProvider = provider || 'gemini';
  return {
    id: id || generateAlternativeId(chosenProvider),
    parentMessageId: parentMessageId || null,
    sender: 'assistant',
    content: typeof content === 'string' ? content : '',
    provider: chosenProvider,
    modelUsed: modelUsed || null,
    responseTimeMs: typeof responseTimeMs === 'number' && !isNaN(responseTimeMs) ? responseTimeMs : null,
    timestamp: timestamp || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    createdAt: typeof createdAt === 'number' && !isNaN(createdAt) ? createdAt : Date.now(),
    referencedAttachments: Array.isArray(referencedAttachments) ? [...referencedAttachments] : [],
    isError: Boolean(isError),
    isStopped: Boolean(isStopped)
  };
}

/**
 * Normalizes an assistant message to ensure it contains a valid alternatives list,
 * an activeAlternativeId, and a linked parentMessageId.
 * Gracefully handles legacy messages that do not have alternative-response metadata.
 *
 * @param {Object} message - The assistant message to normalize
 * @param {Object|null} [precedingUserMessage=null] - Preceding user message for parent linking
 * @returns {Object} Normalized message with alternatives structure
 */
export function normalizeAssistantMessage(message, precedingUserMessage = null) {
  if (!message || message.sender !== 'assistant') {
    return message;
  }

  const parentMessageId =
    message.parentMessageId ||
    (precedingUserMessage?.id ? precedingUserMessage.id : null);

  let alternatives = [];

  if (Array.isArray(message.alternatives) && message.alternatives.length > 0) {
    // Message already has alternatives array; ensure each alternative is well-formed
    alternatives = message.alternatives.map((alt) =>
      createAlternativeRecord({
        id: alt.id,
        parentMessageId: alt.parentMessageId || parentMessageId,
        content: alt.content,
        provider: alt.provider || message.provider || 'gemini',
        modelUsed: alt.modelUsed || message.modelUsed || null,
        responseTimeMs: alt.responseTimeMs,
        timestamp: alt.timestamp || message.timestamp,
        createdAt: alt.createdAt,
        referencedAttachments: alt.referencedAttachments || message.referencedAttachments || [],
        isError: alt.isError,
        isStopped: alt.isStopped
      })
    );
  } else {
    // Legacy message without alternatives: wrap existing message content as Alternative #1
    const initialAltId = message.id ? `alt-${message.id}` : generateAlternativeId(message.provider || 'gemini');
    alternatives = [
      createAlternativeRecord({
        id: initialAltId,
        parentMessageId,
        content: message.content || '',
        provider: message.provider || 'gemini',
        modelUsed: message.modelUsed || null,
        responseTimeMs: message.responseTimeMs,
        timestamp: message.timestamp || '',
        createdAt: message.createdAt || Date.now(),
        referencedAttachments: message.referencedAttachments || [],
        isError: message.isError,
        isStopped: message.isStopped
      })
    ];
  }

  // Ensure activeAlternativeId points to an existing alternative in the list
  let activeAlternativeId = message.activeAlternativeId;
  let activeAlt = alternatives.find((a) => a.id === activeAlternativeId);

  if (!activeAlt) {
    activeAlt = alternatives[0];
    activeAlternativeId = activeAlt.id;
  }

  // Project active alternative's attributes onto the root message object
  return {
    ...message,
    parentMessageId,
    activeAlternativeId,
    alternatives,
    content: activeAlt.content,
    provider: activeAlt.provider,
    modelUsed: activeAlt.modelUsed,
    responseTimeMs: activeAlt.responseTimeMs,
    timestamp: activeAlt.timestamp || message.timestamp,
    referencedAttachments:
      activeAlt.referencedAttachments && activeAlt.referencedAttachments.length > 0
        ? activeAlt.referencedAttachments
        : message.referencedAttachments
  };
}

/**
 * Adds a new alternative response to an assistant message and makes it active.
 * The original response and any previously generated alternatives remain completely unchanged.
 *
 * @param {Object} assistantMessage - Existing assistant message
 * @param {Object} newAlternativeData - Data for the new alternative
 * @returns {Object} Updated assistant message containing all alternatives
 */
export function addAlternativeToAssistantMessage(assistantMessage, newAlternativeData = {}) {
  const normalized = normalizeAssistantMessage(assistantMessage);
  const parentMessageId = normalized.parentMessageId || newAlternativeData.parentMessageId || null;

  const newAlternative = createAlternativeRecord({
    ...newAlternativeData,
    parentMessageId
  });

  const updatedAlternatives = [...normalized.alternatives, newAlternative];

  return {
    ...normalized,
    activeAlternativeId: newAlternative.id,
    alternatives: updatedAlternatives,
    content: newAlternative.content,
    provider: newAlternative.provider,
    modelUsed: newAlternative.modelUsed,
    responseTimeMs: newAlternative.responseTimeMs,
    timestamp: newAlternative.timestamp,
    referencedAttachments:
      newAlternative.referencedAttachments && newAlternative.referencedAttachments.length > 0
        ? newAlternative.referencedAttachments
        : normalized.referencedAttachments
  };
}

/**
 * Switches the active alternative of an assistant message to targetAlternativeId.
 * Updates projected properties (content, provider, model, responseTimeMs) accordingly.
 *
 * @param {Object} assistantMessage - Target assistant message
 * @param {string} targetAlternativeId - ID of alternative to make active
 * @returns {Object} Updated assistant message with newly active alternative projected
 */
export function switchActiveAlternativeInMessage(assistantMessage, targetAlternativeId) {
  if (!assistantMessage || !Array.isArray(assistantMessage.alternatives)) {
    return assistantMessage;
  }

  const targetAlt = assistantMessage.alternatives.find((a) => a.id === targetAlternativeId);
  if (!targetAlt) {
    return assistantMessage;
  }

  return {
    ...assistantMessage,
    activeAlternativeId: targetAlternativeId,
    content: targetAlt.content,
    provider: targetAlt.provider,
    modelUsed: targetAlt.modelUsed,
    responseTimeMs: targetAlt.responseTimeMs,
    timestamp: targetAlt.timestamp || assistantMessage.timestamp,
    referencedAttachments:
      targetAlt.referencedAttachments && targetAlt.referencedAttachments.length > 0
        ? targetAlt.referencedAttachments
        : assistantMessage.referencedAttachments
  };
}

/**
 * Updates properties of the active alternative inside an assistant message.
 * Also synchronizes root projected properties.
 *
 * @param {Object} assistantMessage
 * @param {Object} updates
 * @returns {Object} Updated assistant message
 */
export function updateActiveAlternativeInMessage(assistantMessage, updates = {}) {
  if (!assistantMessage) return assistantMessage;

  const normalized = normalizeAssistantMessage(assistantMessage);
  const activeId = normalized.activeAlternativeId;

  const updatedAlternatives = normalized.alternatives.map((alt) => {
    if (alt.id !== activeId) return alt;
    return {
      ...alt,
      ...updates,
      id: alt.id // Never mutate alternative ID
    };
  });

  const activeAlt = updatedAlternatives.find((a) => a.id === activeId) || updatedAlternatives[0];

  return {
    ...normalized,
    ...updates,
    activeAlternativeId: activeId,
    alternatives: updatedAlternatives,
    content: typeof updates.content === 'string' ? updates.content : activeAlt.content,
    provider: updates.provider || activeAlt.provider,
    modelUsed: updates.modelUsed !== undefined ? updates.modelUsed : activeAlt.modelUsed,
    responseTimeMs:
      updates.responseTimeMs !== undefined ? updates.responseTimeMs : activeAlt.responseTimeMs
  };
}

/**
 * Resolves the currently active alternative record from an assistant message.
 * @param {Object} assistantMessage
 * @returns {Object|null}
 */
export function getActiveAlternative(assistantMessage) {
  if (!assistantMessage) return null;
  const normalized = normalizeAssistantMessage(assistantMessage);
  const alts = Array.isArray(normalized.alternatives) ? normalized.alternatives : [];
  if (alts.length === 0) return null;
  const activeId = normalized.activeAlternativeId;
  return alts.find((a) => a.id === activeId) || alts[0] || null;
}

/**
 * Updates a specific alternative by ID inside an assistant message.
 * If the updated alternative is currently active, root projected properties are synchronized.
 *
 * @param {Object} assistantMessage
 * @param {string} targetId - Alternative ID to update
 * @param {Object} updates
 * @returns {Object} Updated assistant message
 */
export function updateAlternativeByIdInMessage(assistantMessage, targetId, updates = {}) {
  if (!assistantMessage) return assistantMessage;

  const normalized = normalizeAssistantMessage(assistantMessage);
  const targetAlternativeId = targetId || normalized.activeAlternativeId;

  const updatedAlternatives = normalized.alternatives.map((alt) => {
    if (alt.id !== targetAlternativeId) return alt;
    return {
      ...alt,
      ...updates,
      id: alt.id // Never mutate alternative ID
    };
  });

  const activeId = normalized.activeAlternativeId;
  const activeAlt = updatedAlternatives.find((a) => a.id === activeId) || updatedAlternatives[0];

  const rootSync = targetAlternativeId === activeId ? updates : {};

  return {
    ...normalized,
    ...rootSync,
    activeAlternativeId: activeId,
    alternatives: updatedAlternatives,
    content: activeAlt.content,
    provider: activeAlt.provider,
    modelUsed: activeAlt.modelUsed,
    responseTimeMs: activeAlt.responseTimeMs
  };
}

/**
 * Normalizes all messages in a conversation so all assistant messages
 * have parentMessageId and valid alternatives array.
 *
 * @param {Array} messages - Full conversation messages array
 * @returns {Array} Normalized messages array
 */
export function ensureConversationAlternatives(messages = []) {
  if (!Array.isArray(messages)) return [];

  let lastUserMessage = null;

  return messages.map((msg) => {
    if (msg.sender === 'user') {
      lastUserMessage = msg;
      return msg;
    }

    if (msg.sender === 'assistant') {
      const normalized = normalizeAssistantMessage(msg, lastUserMessage);
      return normalized;
    }

    return msg;
  });
}

/**
 * Returns alternative navigation metrics for an assistant message.
 * @param {Object} assistantMessage
 * @returns {{ total: number, currentIndex: number, activeAlternativeId: string|null, canGoPrevious: boolean, canGoNext: boolean, alternatives: Array }}
 */
export function getAlternativeMetrics(assistantMessage) {
  if (!assistantMessage || !Array.isArray(assistantMessage.alternatives)) {
    return {
      total: 1,
      currentIndex: 0,
      activeAlternativeId: assistantMessage?.id || null,
      canGoPrevious: false,
      canGoNext: false,
      alternatives: []
    };
  }

  const alts = assistantMessage.alternatives;
  const total = Math.max(1, alts.length);
  const activeId = assistantMessage.activeAlternativeId || (alts[0]?.id ?? null);
  const currentIndex = Math.max(0, alts.findIndex((a) => a.id === activeId));

  return {
    total,
    currentIndex,
    activeAlternativeId: activeId,
    canGoPrevious: currentIndex > 0,
    canGoNext: currentIndex < total - 1,
    alternatives: alts
  };
}
